import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("submitting a vendor for review", () => {
  test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
    // Arrange: a draft vendor whose only document is an extracted W-9.
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: { name: uniqueName("Rev02 Vendor"), category: "services", contact_email: "rev02@northwind-supply.com" },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const document = (await upload.json()) as { id: string };

    // Extraction runs in the background; wait until the W-9 is extracted.
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/vendors/${vendor.id}/documents`);
          const docs = (await res.json()) as { id: string; status: string }[];
          return docs.find((d) => d.id === document.id)?.status;
        },
        { timeout: 30_000 },
      )
      .toBe("extracted");

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(409);
    const error = (JSON.parse(body) as { error: { code: string; missing_kinds: string[] } }).error;
    expect(error.code, body).toBe("documents_incomplete");
    expect(error.missing_kinds, body).toEqual(["contract", "insurance_certificate"]);
  });
});
